arguments.argument:
//Variable "myroom" stands for the room the animatronic is located
if goingback = 0
    movetime -= 1
else
    backtimer -= 1
//When "movetime" is less than 0, it'll make the animatronic move from one room to another and breaks temporarily the cameras.
if movetime < 0
{
  if myroom != (4)
    movetime = mymovetime
else
    movetime = 50+random(120)
    //Makes animatronic move from one room to another
    if myroom = 0 //If this animatronic is located on Show Stage, move to Dining Area
    {
        if obj_mapcamera1a.on = 1 or obj_mapcamera7.on = 1
        and instance_exists(obj_camera)
        {
            with obj_mapcamera1a broken = 1
            with obj_mapcamera1a alarm[0] = 150
            with obj_mapcamera7 broken = 1
            with obj_mapcamera7 alarm[0] = 150
            sound_play(snd_static)
        }
        myroom = 1
    }
    else if myroom = 1 //If this animatronic is located on Dining Area, move to West Hall 1 or Backstage
    {
        mynextroom = choose(2,3,4) //Chose between Backstage or West Hall 1 
        if mynextroom = 2 //If Backstage is chosen
        {
            if obj_mapcamera7.on = 1 or obj_mapcamera5.on = 1 or obj_mapcamera4b.on = 1
            and instance_exists(obj_camera)
            {
                with obj_mapcamera7 broken = 1
                with obj_mapcamera7 alarm[0] = 150
                with obj_mapcamera5 broken = 1
                with obj_mapcamera5 alarm[0] = 150
                with obj_mapcamera4b broken = 1
                with obj_mapcamera4b alarm[0] = 150
                sound_play(snd_static)
            }
            myroom = 2
        }
        else if mynextroom = 3 //If West Hall 1 is chosen
        {
            if obj_mapcamera7.on = 1 or obj_mapcamera2a.on = 1 or obj_mapcamera4b.on = 1
            and instance_exists(obj_camera)
            {
                with obj_mapcamera7 broken = 1
                with obj_mapcamera7 alarm[0] = 150
                with obj_mapcamera2a broken = 1
                with obj_mapcamera2a alarm[0] = 150
                with obj_mapcamera4b broken = 1
                with obj_mapcamera4b alarm[0] = 150
                sound_play(snd_static)
            }
            myroom = 3
        }
        else if mynextroom = 4
         {
            if obj_mapcamera7.on = 1 or obj_mapcamera2a.on = 1 or obj_mapcamera4b.on = 1
            and instance_exists(obj_camera)
            {
                with obj_mapcamera7 broken = 1
                with obj_mapcamera7 alarm[0] = 150
                with obj_mapcamera2a broken = 1
                with obj_mapcamera2a alarm[0] = 150
                with obj_mapcamera4b broken = 1
                with obj_mapcamera4b alarm[0] = 150
                sound_play(snd_static)
            }
            myroom = 4
        }
    }
    else if myroom = 2 //If this animatronic is located on Backstage, move to West Hall 1 or Dining Area
    {
        mynextroom = choose(1,3,4) //Chose between Dining Area or West Hall 1 
        if mynextroom = 1 //If Dining Area is chosen
        {
            if obj_mapcamera2a.on = 1 or obj_mapcamera5.on = 1 or obj_mapcamera4b.on = 1
            and instance_exists(obj_camera)
            {
                with obj_mapcamera1b broken = 1
                with obj_mapcamera1b alarm[0] = 150
                with obj_mapcamera5 broken = 1
                with obj_mapcamera5 alarm[0] = 150
                with obj_mapcamera4b broken = 1
                with obj_mapcamera4b alarm[0] = 150
                sound_play(snd_static)
            }
            myroom = 1
        }
        else if mynextroom = 3 //If West Hall 1 is chosen
        {
            if obj_mapcamera2a.on = 1 or obj_mapcamera5.on = 1 or obj_mapcamera4b.on = 1
            and instance_exists(obj_camera)
            {
                with obj_mapcamera2a broken = 1
                with obj_mapcamera2a alarm[0] = 150
                with obj_mapcamera5 broken = 1
                with obj_mapcamera5 alarm[0] = 150
                with obj_mapcamera4b broken = 1
                with obj_mapcamera4b alarm[0] = 150
                sound_play(snd_static)
            }
            myroom = 3
        }
         else if mynextroom = 4 //If West Hall 1 is chosen
        {
            if obj_mapcamera2a.on = 1 or obj_mapcamera5.on = 1 or obj_mapcamera4b.on = 1
            and instance_exists(obj_camera)
            {
                with obj_mapcamera2a broken = 1
                with obj_mapcamera2a alarm[0] = 150
                with obj_mapcamera5 broken = 1
                with obj_mapcamera5 alarm[0] = 150
                with obj_mapcamera4b broken = 1
                with obj_mapcamera4b alarm[0] = 150
                sound_play(snd_static)
            }
            myroom = 4
        }

    }
    else if myroom = 3 //If this animatronic is located on West Hall 1, move to West Hall 2
    {
        if obj_mapcamera2a.on = 1 or obj_mapcamera4b.on = 1
        and instance_exists(obj_camera)
        {
            with obj_mapcamera2a broken = 1
            with obj_mapcamera2a alarm[0] = 150
            with obj_mapcamera4b broken = 1
            with obj_mapcamera4b alarm[0] = 150
            sound_play(snd_static)
        }
        myroom = 4
    }
    else if myroom = 4 //If this animatronic is located on West Hall 2, move to office's door
    {
        if obj_mapcamera4b.on = 1
        and instance_exists(obj_camera)
        {
            with obj_mapcamera4b broken = 1
            with obj_mapcamera4b alarm[0] = 150
            sound_play(snd_static)
        }
        myroom = 5 
        global.playrightdoorscaresound = 1
        {

        }
    }
    else if myroom = 5 //If this animatronic is located on office's left door, makes player unable to use left doors or left light buttons
        myroom = 6
}
if backtimer < 0 //Leaves office when right door is closed, and moves back to Dining Area
{
    backtimer = mybacktimer
    myroom = 5
    {
        if obj_mapcamera7.on = 1 
        and instance_exists(obj_camera)
        {
            with obj_mapcamera7 broken = 1
            with obj_mapcamera7 alarm[0] = 150
            sound_play(snd_static)
        }

        movetime = mymovetime
        myroom = 1
           sound_play(snd_leave_vent)
    }
}
